CREATE TABLE IF NOT EXISTS si_plugin_installations (tenant CHAR(32) NOT NULL, plugin VARCHAR(128) NOT NULL, version VARCHAR(64) NOT NULL, package TEXT NOT NULL, installed TINYINT NOT NULL DEFAULT 1, enabled TINYINT NOT NULL DEFAULT 0, PRIMARY KEY(tenant,plugin)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS si_plugin_data (tenant CHAR(32) NOT NULL, plugin VARCHAR(128) NOT NULL, collection VARCHAR(64) NOT NULL, record_id VARCHAR(64) NOT NULL, value LONGTEXT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(tenant,plugin,collection,record_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS si_plugin_migrations (tenant CHAR(32) NOT NULL, plugin VARCHAR(128) NOT NULL, migration VARCHAR(128) NOT NULL, checksum CHAR(64) NOT NULL, status VARCHAR(16) NOT NULL, PRIMARY KEY(tenant,plugin,migration)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS si_plugin_pages (tenant CHAR(32) NOT NULL, plugin VARCHAR(128) NOT NULL, page_key VARCHAR(64) NOT NULL, page_id CHAR(32) NOT NULL, block_id CHAR(32) NOT NULL, sources LONGTEXT NOT NULL, PRIMARY KEY(tenant,plugin,page_key)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
